namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;
    private readonly Lock _lock = new();

    public RecipeService()
    {
        _recipes = GetSeedRecipes();
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        lock (_lock)
        {
            return _recipes
                .Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase))
                .ToList();
        }
    }

    public Recipe? GetById(int id)
    {
        lock (_lock)
        {
            return _recipes.FirstOrDefault(r => r.Id == id);
        }
    }

    public void AddRating(int recipeId, int stars)
    {
        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe is not null && stars is >= 1 and <= 5)
            {
                recipe.TotalRatings++;
                recipe.RatingSum += stars;
            }
        }
    }

    public Recipe AddRecipe(string title, string category, string description,
        List<string> ingredients, List<string> steps)
    {
        lock (_lock)
        {
            var recipe = new Recipe
            {
                Id = _nextId++,
                Title = title,
                Category = category,
                Description = description,
                Ingredients = ingredients,
                Steps = steps
            };
            _recipes.Add(recipe);
            return recipe;
        }
    }

    private static List<Recipe> GetSeedRecipes() =>
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Main Courses",
            Description = "A simple yet delicious Italian pizza with fresh mozzarella and basil.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps = ["Preheat oven to 475°F.", "Roll out dough on a floured surface.", "Spread crushed tomatoes evenly.", "Tear mozzarella and distribute over sauce.", "Bake for 10-12 minutes until crust is golden.", "Top with fresh basil and a drizzle of olive oil."],
            TotalRatings = 12, RatingSum = 52
        },
        new()
        {
            Id = 2, Title = "Caesar Salad", Category = "Salads",
            Description = "Crisp romaine lettuce with creamy Caesar dressing and crunchy croutons.",
            Ingredients = ["Romaine lettuce", "Parmesan cheese", "Croutons", "Caesar dressing", "Lemon juice", "Anchovy paste"],
            Steps = ["Wash and chop romaine lettuce.", "Prepare dressing by mixing Caesar dressing with lemon juice and anchovy paste.", "Toss lettuce with dressing.", "Top with shaved Parmesan and croutons.", "Serve immediately."],
            TotalRatings = 8, RatingSum = 34
        },
        new()
        {
            Id = 3, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Rich chocolate cake with a molten center that flows when cut.",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
            Steps = ["Preheat oven to 425°F.", "Melt chocolate and butter together.", "Whisk eggs and sugar until thick.", "Fold chocolate mixture into eggs.", "Add flour and vanilla, mix gently.", "Pour into greased ramekins and bake 12-14 minutes.", "Invert onto plates and serve immediately."],
            TotalRatings = 15, RatingSum = 71
        },
        new()
        {
            Id = 4, Title = "Tomato Basil Soup", Category = "Soups",
            Description = "A comforting creamy tomato soup with fresh basil.",
            Ingredients = ["Canned tomatoes", "Onion", "Garlic", "Vegetable broth", "Heavy cream", "Fresh basil", "Olive oil"],
            Steps = ["Sauté diced onion and garlic in olive oil.", "Add canned tomatoes and broth.", "Simmer for 20 minutes.", "Blend until smooth.", "Stir in cream and chopped basil.", "Season with salt and pepper."],
            TotalRatings = 6, RatingSum = 25
        },
        new()
        {
            Id = 5, Title = "Bruschetta", Category = "Appetizers",
            Description = "Toasted bread topped with fresh tomatoes, garlic, and basil.",
            Ingredients = ["Baguette", "Tomatoes", "Garlic", "Fresh basil", "Olive oil", "Balsamic vinegar", "Salt"],
            Steps = ["Slice baguette and toast until golden.", "Dice tomatoes and mix with minced garlic, basil, olive oil, and balsamic.", "Season with salt.", "Spoon tomato mixture onto toasted bread.", "Serve immediately."],
            TotalRatings = 10, RatingSum = 42
        },
        new()
        {
            Id = 6, Title = "Grilled Chicken Tacos", Category = "Main Courses",
            Description = "Juicy grilled chicken in warm tortillas with fresh toppings.",
            Ingredients = ["Chicken breast", "Corn tortillas", "Lime", "Cilantro", "Avocado", "Red onion", "Chili powder", "Cumin"],
            Steps = ["Marinate chicken with chili powder, cumin, and lime juice.", "Grill chicken until cooked through.", "Warm tortillas on the grill.", "Slice chicken and place on tortillas.", "Top with diced avocado, red onion, and cilantro.", "Squeeze fresh lime over tacos."],
            TotalRatings = 9, RatingSum = 40
        },
        new()
        {
            Id = 7, Title = "Berry Smoothie", Category = "Beverages",
            Description = "A refreshing blend of mixed berries and yogurt.",
            Ingredients = ["Mixed berries", "Greek yogurt", "Honey", "Milk", "Ice"],
            Steps = ["Add all ingredients to a blender.", "Blend until smooth.", "Pour into a glass and serve."],
            TotalRatings = 5, RatingSum = 22
        },
        new()
        {
            Id = 8, Title = "Greek Salad", Category = "Salads",
            Description = "A fresh Mediterranean salad with feta and olives.",
            Ingredients = ["Cucumber", "Tomatoes", "Red onion", "Kalamata olives", "Feta cheese", "Olive oil", "Oregano"],
            Steps = ["Chop cucumber, tomatoes, and red onion.", "Combine vegetables in a bowl.", "Add olives and crumbled feta.", "Drizzle with olive oil and sprinkle oregano.", "Toss gently and serve."],
            TotalRatings = 7, RatingSum = 30
        }
    ];
}

