@* Interactive star-rating widget — opt-in to InteractiveServer *@
@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= DisplayRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => _hoverRating = star"
              @onmouseout="() => _hoverRating = 0"
              title="Rate @star star@(star > 1 ? "s" : "")">
            @(star <= DisplayRating ? "★" : "☆")
        </span>
    }
    @if (TotalRatings > 0)
    {
        <span class="rating-info">@AverageRating.ToString("F1") avg (@TotalRatings ratings)</span>
    }
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>

<style>
    .star-rating {
        display: flex;
        align-items: center;
        gap: 2px;
        margin: 0.5rem 0;
    }
    .star {
        font-size: 1.8rem;
        cursor: pointer;
        color: #ccc;
        transition: color 0.15s;
        user-select: none;
    }
    .star.filled {
        color: #f4a623;
    }
    .star:hover {
        color: #f4a623;
    }
    .rating-info {
        margin-left: 0.75rem;
        font-size: 0.9rem;
        color: #666;
    }
    .rating-thanks {
        margin-left: 0.75rem;
        font-size: 0.9rem;
        color: #28a745;
        font-weight: 500;
    }
</style>

@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

    [Parameter]
    public double AverageRating { get; set; }

    [Parameter]
    public int TotalRatings { get; set; }

    [Parameter]
    public EventCallback<int> OnRated { get; set; }

    private int _hoverRating;
    private int _userRating;
    private bool _submitted;

    private int DisplayRating => _hoverRating > 0 ? _hoverRating : _userRating;

    private async Task Rate(int stars)
    {
        _userRating = stars;
        _submitted = true;
        await OnRated.InvokeAsync(stars);
    }
}

