    @if (_recipe is not null)
    {
        @: &rsaquo; <a href="recipes/@Uri.EscapeDataString(_recipe.Category)">@_recipe.Category</a>
    }
    &rsaquo; <strong>@(_recipe?.Title ?? "Recipe")</strong>
</nav>

@if (_recipe is null)
{
    <h1>Recipe not found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
}
else
{
    <h1>@_recipe.Title</h1>
    <p class="recipe-description">@_recipe.Description</p>

    <StarRating RecipeId="@_recipe.Id"
                AverageRating="@_recipe.AverageRating"
                TotalRatings="@_recipe.TotalRatings"
                OnRated="HandleRating" />

    <section class="recipe-section">
        <h2>🧾 Ingredients</h2>
        <ul>
            @foreach (var ingredient in _recipe.Ingredients)
            {
                <li>@ingredient</li>
            }
        </ul>
    </section>

    <section class="recipe-section">
        <h2>👩‍🍳 Steps</h2>
        <ol>
            @foreach (var step in _recipe.Steps)
            {
                <li>@step</li>
            }
        </ol>
    </section>
}

<style>
    nav {
        margin-bottom: 1rem;
        font-size: 0.95rem;
    }
    nav a {
        color: #0d6efd;
        text-decoration: none;
    }
    .recipe-description {
        font-size: 1.1rem;
        color: #555;
        margin-bottom: 1rem;
    }
    .recipe-section {
        margin: 1.5rem 0;
