+        </div>
+
+        <div class="form-group">
+            <label for="description">Short Description</label>
+            <InputTextArea id="description" @bind-Value="_model.Description" class="form-control" rows="2"
+                           placeholder="A brief description of your recipe" />
+            <ValidationMessage For="() => _model.Description" />
+        </div>
+
+        <div class="form-group">
+            <label for="ingredients">Ingredients (one per line)</label>
+            <InputTextArea id="ingredients" @bind-Value="_model.IngredientsText" class="form-control" rows="5"
+                           placeholder="1 cup flour&#10;2 eggs&#10;1/2 cup sugar" />
+            <ValidationMessage For="() => _model.IngredientsText" />
+        </div>
+
+        <div class="form-group">
+            <label for="steps">Steps (one per line)</label>
+            <InputTextArea id="steps" @bind-Value="_model.StepsText" class="form-control" rows="5"
+                           placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Add wet ingredients and stir." />
+            <ValidationMessage For="() => _model.StepsText" />
+        </div>
+
+        <button type="submit" class="btn-submit">Submit Recipe</button>
+    </EditForm>
+}
+
+<style>
+    nav {
+        margin-bottom: 1rem;
+        font-size: 0.95rem;
+    }
+    nav a {
+        color: #0d6efd;
+        text-decoration: none;
+    }
+    .form-group {
+        margin-bottom: 1.25rem;
+    }
+    .form-group label {
+        display: block;
+        font-weight: 600;
+        margin-bottom: 0.3rem;
+    }
+    .form-control {
+        width: 100%;
+        max-width: 600px;
+        padding: 0.5rem;
+        border: 1px solid #ccc;
+        border-radius: 4px;
+        font-size: 1rem;
+    }
+    .form-control:focus {
+        outline: none;
+        border-color: #0d6efd;
+        box-shadow: 0 0 0 2px rgba(13, 110, 253, 0.15);
+    }
+    .btn-submit {
+        padding: 0.6rem 2rem;
+        background: #198754;
+        color: white;
+        border: none;
+        border-radius: 6px;
+        font-size: 1rem;
+        font-weight: 500;
+        cursor: pointer;
+    }
+    .btn-submit:hover {
+        background: #157347;
+    }
+    .validation-message {
+        color: #dc3545;
+        font-size: 0.875rem;
+        margin-top: 0.25rem;
+    }
+    .success-message {
+        padding: 1.5rem;
+        background: #d1e7dd;
+        border-radius: 8px;
+        margin-top: 1rem;
+    }
+    .success-message a {
+        color: #0d6efd;
+    }
+</style>
+
+@code {
+    [SupplyParameterFromForm]
+    private RecipeFormModel _model { get; set; } = new();
+
+    private bool _submitted;
+    private int _createdId;
+
+    private void HandleSubmit()
+    {
+        var ingredients = _model.IngredientsText
+            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
+            .ToList();
+
+        var steps = _model.StepsText
+            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
+            .ToList();
+
+        var recipe = RecipeService.AddRecipe(
+            _model.Title, _model.Category, _model.Description, ingredients, steps);
+
+        _createdId = recipe.Id;
+        _submitted = true;
+    }
+
+    private sealed class RecipeFormModel
+    {
+        [Required(ErrorMessage = "Please enter a recipe title.")]
+        [StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be 3-100 characters.")]
+        public string Title { get; set; } = string.Empty;
+
+        [Required(ErrorMessage = "Please select a category.")]
+        public string Category { get; set; } = string.Empty;
+
+        [Required(ErrorMessage = "Please enter a description.")]
+        [StringLength(300, MinimumLength = 10, ErrorMessage = "Description must be 10-300 characters.")]
+        public string Description { get; set; } = string.Empty;
+
+        [Required(ErrorMessage = "Please enter at least one ingredient.")]
+        public string IngredientsText { get; set; } = string.Empty;
+
+        [Required(ErrorMessage = "Please enter at least one step.")]
+        public string StepsText { get; set; } = string.Empty;
+    }
+}
